export const translation_fallback = 'NO_TRANSLATION_FOUND';

interface translations {
	[key: string]: translation;
}

interface translation_leaf {
	en?: string;
	de?: string;
	es?: string;
	it?: string;
	ja?: string;
	pl?: string;
	pt?: string;
	sv?: string;
	ru?: string;
	zh?: string;
}

export type translation = translation_leaf | {
	[key: string]: translation;
};

export function tl(
	key: translation | string,
	replacements: Record<string, ReactNode> = {},
	string = true,
) {
	if (typeof key === 'string') {
		if (lang == 'fae') return 'hazelfae';

		return key;
	}

	if (!key) {
		log('your key is undefined', 'trans');
		if (lang == 'fae') return 'hazelfae';

		return translation_fallback;
	}

	let translation = (key[lang] || key.en) as string;

	if (page.state.april && translation.includes('Last.fm Pro')) {
		translation = translation.replaceAll('Last.fm Pro', 'Verified');
	}

	if (Object.keys(replacements).length == 0) {
		if (lang == 'fae') {
			return 'hazelfae';
		}

		return translation;
	}

	if (string) {
		for (let [placeholder, value] of Object.entries(replacements)) {
			const regex = new RegExp(`{${placeholder}}`, 'g');
			if (lang == 'fae') value = 'hazelfae';
			translation = translation.replace(regex, value);
		}

		return translation;
	}

	const parts = translation.split(/({[^}]+})/g);

	return parts.map((part) => {
		const match = part.match(/^\{(\w+)\}$/);
		if (lang == 'fae') return 'hazelfae';

		if (match) {
			const key = match[1];

			return replacements[key] ?? part;
		}

		return part;
	});
}

function collect_keys(object, prefix, out = []) {
	for (const k in object) {
		const val = object[k];
		const key = prefix ? `${prefix}.${k}` : k;

		if (
			typeof val == 'object' &&
			!Object.keys(lang_info).some((lang) => lang in val)
		) {
			collect_keys(val, key, out);
		} else {
			out.push(key);
		}
	}

	return out;
}

function get_value_by_path(object, path) {
	return path.split('.').reduce((acc, part) => acc?.[part], object);
}

export function translation_stats() {
	const keys = collect_keys(trans);

	for (const lang of Object.keys(lang_info)) {
		let translated = 0;
		const missing = [];

		for (const key of keys) {
			const value = get_value_by_path(trans, key);
			if (value && value[lang]) {
				translated++;
			} else {
				missing.push(key);
			}
		}

		lang_info[lang].total = keys.length;
		lang_info[lang].translated = translated;
		lang_info[lang].missing = missing.length;
		lang_info[lang].missing_keys = missing;
		lang_info[lang].percent = Math.round((translated / keys.length) * 100);
	}

	log('translation stats', 'trans', 'info', { lang_info });
}

function get_lang() {
	const path = window.location.pathname;
	const segments = path.split('/');
	const lang = segments[1];

	if (/^[a-z]{2}$/.test(lang)) {
		return `/${lang}/`;
	}

	return '/';
}

export function lookup_lang() {
	setRoot(get_lang());

	const params = new URLSearchParams(document.location.search);
	const hazelfae = params.get('hazelfae');

	if (!page.state.hazelfae) {
		page.state.hazelfae = hazelfae != undefined;
	}

	if (page.state.hazelfae) {
		lang = 'fae';
	} else {
		lang = document.documentElement.getAttribute('lang');
	}

	lang_browser = navigator.language.replaceAll('"', '');

	if (lang.startsWith('en') && lang_browser.startsWith('en')) {
		Settings.defaultLocale = lang_browser;
	} else {
		Settings.defaultLocale = lang;
	}

	log(`using locale ${Settings.defaultLocale}`, 'lang', 'info', {
		lang,
		lang_browser,
	});
}

export function get_trans_key(key) {
	return key.split('.').reduce((trans, key) => trans[key], trans);
}
